import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.CZqXuAiL.js";const b=JSON.parse('{"title":"Using the Theme — Apple","description":"Daily use of the Apple admin theme — light/dark toggle, sidebar rail and filter, mobile drawer, bento dashboard and the boot loader.","frontmatter":{"title":"Using the Theme — Apple","description":"Daily use of the Apple admin theme — light/dark toggle, sidebar rail and filter, mobile drawer, bento dashboard and the boot loader."},"headers":[],"relativePath":"apple/user-guide/using-the-theme.md","filePath":"apple/user-guide/using-the-theme.md","lastUpdated":1785521346000}'),r={name:"apple/user-guide/using-the-theme.md"};function n(s,e,l,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="using-the-theme" tabindex="-1">Using the Theme <a class="header-anchor" href="#using-the-theme" aria-label="Permalink to &quot;Using the Theme&quot;">​</a></h1><p>Everything an admin touches day to day. None of it requires the settings hub — these controls live directly in the interface.</p><h2 id="light-dark-toggle" tabindex="-1">Light / dark toggle <a class="header-anchor" href="#light-dark-toggle" aria-label="Permalink to &quot;Light / dark toggle&quot;">​</a></h2><p>The sun/moon button in the top bar flips between Catppuccin Latte (light) and Mocha (dark) instantly — no page reload. The choice persists in your browser (<code>localStorage: apple-mode</code>) and beats the panel-wide default set in the hub.</p><div class="info custom-block"><p class="custom-block-title">Per browser, not per account</p><p>The toggle state lives in <code>localStorage</code>, so it follows the browser, not your admin account. There is deliberately no server round-trip for a visual preference.</p></div><h2 id="the-sidebar" tabindex="-1">The sidebar <a class="header-anchor" href="#the-sidebar" aria-label="Permalink to &quot;The sidebar&quot;">​</a></h2><h3 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h3><p>Sections and links are exactly the ones the panel itself defines — core pages under their usual headers, plus every link any extension registers. The active page is marked by a tinted row where <strong>only the icon carries the accent color</strong>; labels always stay neutral for readability.</p><h3 id="filter" tabindex="-1">Filter <a class="header-anchor" href="#filter" aria-label="Permalink to &quot;Filter&quot;">​</a></h3><p>The field at the top filters links by label as you type. Sections with no matching links collapse away; a &quot;No matching entries&quot; row appears when nothing hits. Clear the field to restore the full menu.</p><h3 id="icon-rail" tabindex="-1">Icon rail <a class="header-anchor" href="#icon-rail" aria-label="Permalink to &quot;Icon rail&quot;">​</a></h3><p>The toggle in the sidebar footer collapses the sidebar to a 76px icon-only rail (labels, sections and the filter hide; everything stays one click away). Your choice persists (<code>localStorage: apple-rail</code>). The panel-wide default is settable in the hub.</p><h3 id="mobile-drawer" tabindex="-1">Mobile drawer <a class="header-anchor" href="#mobile-drawer" aria-label="Permalink to &quot;Mobile drawer&quot;">​</a></h3><p>At ≤ 992px the sidebar becomes an off-canvas drawer: the hamburger in the top bar opens it over a blurred backdrop, and tapping the backdrop, pressing <code>Esc</code>, or picking a link closes it. The rail setting is ignored on mobile — the drawer always shows labels.</p><h2 id="the-top-bar" tabindex="-1">The top bar <a class="header-anchor" href="#the-top-bar" aria-label="Permalink to &quot;The top bar&quot;">​</a></h2><p>A floating glass bar with the current page title, the mode toggle, and your account actions (account, extensions, exit to the client panel, logout) moved from the stock header. The logout keeps the panel&#39;s own confirmation dialog — Apple moves the original buttons, it does not re-implement them.</p><h2 id="bento-dashboard" tabindex="-1">Bento dashboard <a class="header-anchor" href="#bento-dashboard" aria-label="Permalink to &quot;Bento dashboard&quot;">​</a></h2><p>The admin home page renders a bento grid:</p><table tabindex="0"><thead><tr><th>Tile</th><th>Contents</th></tr></thead><tbody><tr><td>Hero</td><td>Time-of-day greeting, panel-wide counts, and a live version status pill (up to date / update available with a release link)</td></tr><tr><td>Activity</td><td>New accounts over the last 14 days with an inline SVG sparkline — no chart library, no CDN</td></tr><tr><td>Stats</td><td>Servers, users, nodes and locations as link tiles with per-tile hues</td></tr><tr><td>Quick actions</td><td>New server, new user, new node, panel settings, Application API, Extensions</td></tr><tr><td>System</td><td>Panel version, PHP version, render time, and quiet links (docs, GitHub, Discord, donate)</td></tr></tbody></table><p>Turn it off in the hub (<strong>Bento dashboard</strong> switch) and the stock dashboard renders instead — the fallback ships inside the same file, nothing to reinstall.</p><h2 id="boot-loader" tabindex="-1">Boot loader <a class="header-anchor" href="#boot-loader" aria-label="Permalink to &quot;Boot loader&quot;">​</a></h2><p>Every admin page opens with a short branded splash — your panel name under the Apple glyph with an accent progress ring — while the theme builds its chrome. It fades the moment the interface is ready and never blocks longer than ~3 seconds even if scripts fail (a CSS-only failsafe hides it). With reduced motion enabled, the ring is static and the fade is instant.</p><h2 id="keyboard-and-motion" tabindex="-1">Keyboard and motion <a class="header-anchor" href="#keyboard-and-motion" aria-label="Permalink to &quot;Keyboard and motion&quot;">​</a></h2><ul><li><code>Esc</code> closes the mobile drawer.</li><li>Every interactive element has a visible focus ring (2px accent at 45%).</li><li>All transitions run 150–250ms and respect <code>prefers-reduced-motion</code> everywhere, always — the hub&#39;s <strong>Animations</strong> switch can only turn motion off, never override a user&#39;s OS preference.</li></ul>',24)])])}const u=t(r,[["render",n]]);export{b as __pageData,u as default};
